use owner::JournalOwner;use owner_budget::OwnerBudget;use ingetrazo_core::mesh::Mesh;use glam::DVec3;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};static ALLOCATIONS:AtomicUsize=AtomicUsize::new(0);struct Count;unsafe impl GlobalAlloc for Count{unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCATIONS.fetch_add(1,Ordering::Relaxed);unsafe{System.alloc(l)}}unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{ALLOCATIONS.fetch_add(1,Ordering::Relaxed);unsafe{System.alloc_zeroed(l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCATIONS.fetch_add(1,Ordering::Relaxed);unsafe{System.realloc(p,l,n)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}}#[global_allocator]static GLOBAL:Count=Count;
fn transaction(o:&JournalOwner,x:f64)->owner::Transaction{let mut t=o.try_begin().unwrap();t.add_edge(DVec3::new(x,0.,0.),DVec3::new(x+1.,0.,0.)).unwrap();t}
fn main(){
 let budget=OwnerBudget::new(None);let mut a=JournalOwner::new_with_budget(Mesh::new(),budget.clone()).unwrap();let mut b=JournalOwner::new_with_budget(Mesh::new(),budget.clone()).unwrap();
 a.commit(transaction(&a,0.)).unwrap();a.undo().unwrap();let before=a.history_counts();let charges=budget.snapshot().total();
 let ta=transaction(&a,2.);let tb=transaction(&b,4.);let pa=a.prepare(ta).unwrap().unwrap();budget.set_limit(Some(budget.snapshot().total()));assert!(b.prepare(tb).is_err());drop(pa);budget.set_limit(None);
 assert!(a.mesh().vertices.is_empty());assert_eq!(a.history_counts(),before);assert!(b.mesh().vertices.is_empty());assert_eq!(b.history_counts(),(0,0));assert_eq!(budget.snapshot().total(),charges);
 a.redo().unwrap();let held=a.try_begin().unwrap();let ta=transaction(&a,2.);let tb=transaction(&b,4.);let pa=a.prepare(ta).unwrap().unwrap();let pb=b.prepare(tb).unwrap().unwrap();let allocations=ALLOCATIONS.load(Ordering::Relaxed);pa.apply();pb.apply();assert_eq!(ALLOCATIONS.load(Ordering::Relaxed),allocations);assert!(a.commit(held).is_err());assert_eq!(a.mesh().edges.len(),2);assert_eq!(b.mesh().edges.len(),1);a.undo().unwrap();b.undo().unwrap();a.redo().unwrap();b.redo().unwrap();assert_eq!(a.mesh().edges.len(),2);assert_eq!(b.mesh().edges.len(),1);
 let mut fa=face_owner::FaceOwner::new_with_budget(Mesh::new(),budget.clone()).unwrap();let mut fb=face_owner::FaceOwner::new_with_budget(Mesh::new(),budget.clone()).unwrap();let ring=[DVec3::ZERO,DVec3::X,DVec3::Y];let mut t=fa.begin().unwrap();t.add_face(&ring,&[]).unwrap();fa.commit(t).unwrap();fa.undo().unwrap();let fc=fa.history_counts();let charges=budget.snapshot().total();let mut ta=fa.begin().unwrap();ta.add_face(&ring,&[]).unwrap();let mut tb=fb.begin().unwrap();tb.add_face(&ring,&[]).unwrap();let pa=fa.prepare(ta).unwrap().unwrap();budget.set_limit(Some(budget.snapshot().total()));assert!(fb.prepare(tb).is_err());drop(pa);budget.set_limit(None);assert_eq!(fa.history_counts(),fc);assert!(fa.mesh().faces.is_empty());assert!(fb.mesh().faces.is_empty());assert_eq!(budget.snapshot().total(),charges);fa.redo().unwrap();let mut ta=fa.begin().unwrap();ta.add_face(&ring,&[]).unwrap();let mut tb=fb.begin().unwrap();tb.add_face(&ring,&[]).unwrap();let pa=fa.prepare(ta).unwrap().unwrap();let pb=fb.prepare(tb).unwrap().unwrap();let allocations=ALLOCATIONS.load(Ordering::Relaxed);pa.apply();pb.apply();assert_eq!(ALLOCATIONS.load(Ordering::Relaxed),allocations);assert_eq!(fa.mesh().faces.len(),2);assert_eq!(fb.mesh().faces.len(),1);fa.undo().unwrap();fa.redo().unwrap();fb.undo().unwrap();fb.redo().unwrap();assert_eq!(fa.mesh().faces.len(),2);assert_eq!(fb.mesh().faces.len(),1);drop(fa);drop(fb);
 drop(a);drop(b);assert_eq!(budget.snapshot().total(),0);println!("{}",serde_json::json!({"two_owner_prepare_refusal_preserves_both":true,"preexisting_redo_preserved":true,"prepared_drop_releases_charges":true,"two_owner_apply":true,"application_allocations":0,"two_face_owner_prepare_refusal":true,"face_existing_boundary_publication":true,"stale_transaction_rejected":true,"undo_redo":true,"final_zero":true,"production_enabled":false}));
}
